// Üretilen dosya: tool/ozgun/uret.py. İstatistik ve Veri Bilimi · Genel ek sorular: İstatistik ve Veri Bilimi kategorisinde bankada henüz sorulmamış bilgi ve beceriler (bu kategorinin alt alanları: Merkezî eğilim ve yayılım ölçüleri (her soru kendi verisini içerir) | Olasılık ve olasılık dağılımlarına giriş | Veri toplama, örnekleme, anket ve grafik yorumlama (veri metinde verilir) | Veri bilimi kavramları, korelasyon, istatistiksel yanılgılar) (zor).
const ozStatistics5Zor = <(String, String, List<String>, String)>[
  ('Çebişev eşitsizliği, Markov eşitsizliğinden nasıl türetilebilir?', 'Markov\'u (X − μ)² değişkenine uygulayarak', ['Markov eşitsizliğini X + μ değişkenine uygulayarak', 'Merkezî limit teoremini Markov sınırıyla çarparak', 'Markov eşitsizliğini √X değişkenine uygulayarak'], 'P(|X − μ| ≥ kσ) = P((X − μ)² ≥ k²σ²) ≤ σ²/(k²σ²) = 1/k² olur; bu Markov\'un (X − μ)²\'ye uygulanmasıdır.'),
  ('Gelir dağılımını göstermek için kullanılan eğriyi 1905\'te öneren Max O. Lorenz hangi ülkenin iktisatçısıdır?', 'Amerika Birleşik Devletleri', ['Almanya', 'Avusturya-Macaristan', 'Birleşik Krallık'], 'Max Otto Lorenz, eğriyi 1905\'te bir Amerikan istatistik dergisinde yayımlamış Amerikalı bir iktisatçıdır.'),
  ('Gini katsayıları birbirine tam olarak eşit çıkan iki ülke için hangisi doğrudur?', 'Lorenz eğrileri farklı biçimlerde olabilir', ['Ortalama gelirleri kesinlikle eşittir', 'En yoksul %10\'un gelir payları kesinlikle eşittir', 'Lorenz eğrileri tam olarak çakışır'], 'Kesişen iki farklı Lorenz eğrisi eşitlik doğrusuyla aynı büyüklükte alan sınırlayabilir; bu yüzden tek bir Gini değeri dağılımın biçimini tam anlatmaz.'),
  ('Bir ülkede herkesin gelirine aynı sabit tutar (örneğin aylık 1000 TL) eklenirse Gini katsayısı genellikle nasıl değişir?', 'Azalır', ['Artar', 'Değişmez', 'Önce artar, sonra sıfıra iner'], 'Sabit ekleme kişiler arasındaki mutlak farkları değiştirmez ama ortalamayı büyütür; farkların ortalamaya oranı küçüldüğü için eşitsizlik azalır.'),
  ('A malının fiyatı 10 TL\'den 12 TL\'ye, B malının fiyatı 20 TL\'den 18 TL\'ye değişmiştir. Baz dönemde A\'dan 5, B\'den 2 birim alınmıştır. Laspeyres fiyat endeksi yaklaşık kaçtır?', '106,7', ['100', '104,55', '110'], 'Σp₁q₀ = 12·5 + 18·2 = 96, Σp₀q₀ = 10·5 + 20·2 = 90; endeks (96 / 90) × 100 ≈ 106,7\'dir.'),
  ('Laspeyres tipi bir tüketici fiyat endeksinin yaşam maliyeti artışını olduğundan yüksek gösterme eğiliminin temel nedeni nedir?', 'Pahalanan maldan ucuzlayana kaymayı yansıtmaması', ['Baz yılının endeks değerinin 100 alınması', 'Fiyatların geometrik ortalamayla birleştirilmesi', 'Cari dönemin miktarlarını ağırlık olarak kullanması'], 'Sabit baz sepeti, fiyatı artan maldan daha az alınmasını hesaba katmaz; bu \'ikame yanlılığı\' artışı abartır.'),
  ('İki malın fiyatlarından biri %50 artmış, öteki %50 azalmıştır. Fiyat göreliklerinin (150 ve 50) geometrik ortalamasıyla hesaplanan endeks yaklaşık kaçtır?', '86,6', ['100', '75', '93,30'], 'Geometrik ortalama √(150 × 50) ≈ 86,6\'dır; aritmetik ortalama ise 100 verirdi.'),
  ('Bir sürecin Cp değeri yüksek, Cpk değeri ise düşük çıkmıştır. Bu durumun en olası açıklaması nedir?', 'Dağılım dar ama ortalama merkezden kaymıştır', ['Dağılım çok geniş ama ortalama tam merkezdedir', 'Süreçte ölçülebilir hiçbir değişkenlik bulunmamaktadır', 'Şartname sınırları yanlış girilmiştir'], 'Cp yalnız yayılımı toleransla karşılaştırır; Cpk ise ortalamanın en yakın sınıra uzaklığını da hesaba katar. Aradaki fark merkezden kaymayı gösterir.'),
  ('Üç kutudan birinde iki altın, birinde iki gümüş, birinde bir altın bir gümüş para vardır. Rastgele seçilen kutudan rastgele çekilen para altın çıkıyor. Aynı kutudaki öteki paranın da altın olma olasılığı kaçtır?', '2/3', ['1/2', '1/3', '3/4'], 'Bertrand\'ın kutu paradoksudur: çekilebilecek üç altın paradan ikisi altın-altın kutusundadır, bu yüzden olasılık 2/3 olur.'),
  ('Daniel Bernoulli\'nin 1738\'de St. Petersburg paradoksuna önerdiği çözüm hangi düşünceye dayanır?', 'Paranın faydasının azalarak artmasına', ['Büyük sayılar yasasının kısa dönemde işlememesine', 'Kumarbazın kayıplarını telafi etme eğilimine', 'Bayes teoremiyle önsel inancın güncellenmesine'], 'Bernoulli, kişinin paranın kendisini değil faydasını (örneğin logaritmasını) değerlendirdiğini öne sürdü; bu beklenen fayda kuramının başlangıcıdır.'),
  ('İki zarftan birinde ötekinin iki katı para vardır. Açtığınız zarfta x TL görüp \'öteki zarfta yarı olasılıkla 2x, yarı olasılıkla x/2 var; beklenen değer 1,25x, öyleyse değiştirmeliyim\' diye düşünüyorsunuz. Bu akıl yürütmedeki hata nedir?', 'x\'i iki durumda da aynı sabit tutar sayması', ['Paraların toplamını hesaba katmaması', 'Zarfların renklerinin farklı olabileceğini unutması', 'Beklenen değer yerine medyan kullanması'], 'İki zarf paradoksunda aynı x simgesi iki farklı durumu temsil eder; zarfların toplamı T sabit alınırsa değiştirmenin beklenen kazancı sıfır çıkar.'),
  ('Bir kavanozda 1 kırmızı ve 1 mavi top vardır. Çekilen top geri konur ve aynı renkten bir top daha eklenir. İlk çekilişin sonucunu bilmeyen biri için ikinci çekilişte kırmızı top gelme olasılığı kaçtır?', '1/2', ['2/3', '1/3', '3/4'], 'Pólya kavanozunda: (1/2)·(2/3) + (1/2)·(1/3) = 1/2. Sonuç bilinmedikçe ikinci çekilişin olasılığı ilkiyle aynıdır.'),
  ('Bertrand\'ın kiriş paradoksunda bir çemberde \'rastgele\' çizilen kirişin iç teğet eşkenar üçgenin kenarından uzun olma olasılığı için 1/3, 1/2 ve 1/4 gibi farklı yanıtlar bulunur. Bunun nedeni nedir?', 'Rastgele seçim tek biçimde tanımlı değildir', ['Çemberin yarıçapının verilmemesi', 'Eşkenar üçgenin kenarının hesaplanamaması', 'Olasılığın 1\'den büyük çıkması'], 'Kiriş uç noktalarıyla, orta noktasıyla ya da yarıçap üzerindeki uzaklığıyla seçilebilir; her yöntem farklı bir olasılık dağılımı verir.'),
  ('Maurice Allais\'nin 1953\'te ortaya koyduğu paradoks, insanların seçimlerinde hangi kuramın öngörülerinden sistematik olarak saptığını gösterir?', 'Beklenen fayda kuramı', ['Büyük sayılar yasası', 'Merkezî limit teoremi', 'Bayes teoremi ve önsel olasılık'], 'Allais paradoksu, kesin kazancın aşırı değerli bulunduğunu (kesinlik etkisi) ve bunun beklenen fayda kuramının bağımsızlık aksiyomuyla çeliştiğini gösterir.'),
  ('Edmond Halley\'nin 1693\'te Breslau kentinin doğum ve ölüm kayıtlarından hazırladığı yaşam tablosu en çok hangi alanda önem kazanmıştır?', 'Ömür boyu gelir sigortalarının fiyatlanmasında', ['Kuyruklu yıldızların yörüngelerinin hesaplanmasında', 'Seçim sonuçlarının tahmin edilmesinde', 'Tarım ürünlerinin vergilendirilmesinde'], 'Halley\'nin tablosu her yaşta hayatta kalma olasılıklarını verdi; bu da yıllık gelir (annuite) ödemelerinin bilimsel olarak fiyatlanmasını sağladı.'),
  ('İkinci Dünya Savaşı\'nda Londra\'ya düşen V-1 bombalarının bazı semtlerde kümelendiği düşünülüyordu. R. D. Clarke\'ın 1946\'daki çözümlemesi bu konuda neyi gösterdi?', 'Dağılımın Poisson modeline, yani rastgeleliğe uyduğunu', ['Bombaların belirli hedeflere kesin olarak yöneltildiğini', 'Kümelenmenin yalnız gece saldırılarında görüldüğünü', 'Bombaların düzgün aralıklarla düştüğünü'], 'Clarke, Güney Londra\'yı eşit karelere bölüp isabet sayılarının Poisson dağılımına çok iyi uyduğunu gösterdi; görülen kümeler rastlantının doğal sonucuydu.'),
  ('Güneşli günden güneşli güne geçiş olasılığı 0,8, yağmurlu günden güneşli güne geçiş olasılığı 0,4 olan iki durumlu bir hava zincirinde uzun dönemde günlerin hangi oranı güneşli olur?', '2/3', ['1/2', '4/5', '3/5'], 'Durağan dağılımda π·0,2 = (1 − π)·0,4 olmalıdır (güneşliden çıkış = güneşliye giriş); buradan π = 0,4/0,6 = 2/3 bulunur.'),
  ('Hilesiz bir zarın altı yüzünün hepsini en az bir kez görmek için beklenen atış sayısı yaklaşık kaçtır?', '14,7', ['6', '21', '10,25'], 'Kupon toplayıcı probleminde beklenen sayı n·(1 + 1/2 + … + 1/n)\'dir: 6·2,45 = 14,7.'),
  ('Hilesiz bir para atılıyor. Üçüncü yazının tam olarak beşinci atışta gelme olasılığı kaçtır?', '3/16', ['5/16', '1/8', '3/32'], 'İlk dört atışta tam iki yazı olmalı (C(4,2) = 6 yol) ve beşinci atış yazı gelmelidir: 6·(1/2)⁵ = 6/32 = 3/16.'),
  ('Hilesiz bir para atılıyor ve önce yazı, hemen ardından tura (YT) dizisi ilk kez görülünce duruluyor. Beklenen atış sayısı kaçtır?', '4', ['6', '3', '8'], 'İlk yazıyı beklemek ortalama 2, ardından ilk turayı beklemek ortalama 2 atış sürer; yazıdan sonra gelen yazı ilerlemeyi bozmaz. Toplam 4.'),
  ('Durağan bir toplulukta bir hastalığın yıllık insidansı binde 2, hastalığın ortalama süresi 5 yıldır. Prevalans yaklaşık binde kaçtır?', '10', ['2', '7', '2,5'], 'Hastalık seyrek ve durum durağansa prevalans ≈ insidans × ortalama süre = 2 × 5 = binde 10\'dur.'),
  ('Vaka-kontrol çalışmalarında maruz kalanlar ile kalmayanlar arasında doğrudan göreli risk hesaplanamamasının nedeni nedir?', 'Vaka-kontrol oranını araştırmacı seçer', ['Bu çalışmalarda maruziyet bilgisi toplanmaz', 'Bu çalışmalarda hiç hasta bulunmaz', 'Örneklem her zaman çok büyüktür'], 'Hasta ve sağlıklı oranı tasarımla seçildiğinden gruplardaki hastalık oranları topluluğu yansıtmaz; bu yüzden riskler yerine odds oranı kullanılır.'),
  ('Kuzey, Orta ve Güney değerlerini alan \'bölge\' değişkeni, sabit terim içeren bir regresyon modeline kaç tane 0/1 kukla değişkenle katılmalıdır?', '2', ['3', '1', '6'], 'k kategorili bir değişken için k − 1 kukla yeterlidir; üçünü birden eklemek sabit terimle tam doğrusal bağımlılık (kukla değişken tuzağı) yaratır.'),
  ('Bir modelde hem talep hem fiyatın logaritması alınmış ve ln(talep) = 8 − 1,5·ln(fiyat) bulunmuştur. Fiyat %1 artarsa talep yaklaşık nasıl değişir?', 'Yaklaşık %1,5 azalır', ['Yaklaşık 1,5 birim azalır', 'Yaklaşık %15 azalır', 'Yaklaşık %1,5 artar'], 'Log-log modelde eğim esneklik olarak yorumlanır: fiyattaki %1\'lik artış talepte yaklaşık %1,5\'lik düşüş demektir.'),
  ('Aynı veride y\'nin x\'e göre regresyon doğrusunun eğimi 0,8, x\'in y\'ye göre regresyon doğrusunun eğimi 0,45\'tir. Korelasyon katsayısının mutlak değeri kaçtır?', '0,6', ['0,36', '0,625', '1,25'], 'İki eğimin çarpımı r²\'ye eşittir: 0,8 · 0,45 = 0,36; buradan |r| = 0,6 bulunur.'),
  ('Bir mağazanın satışlarında her yıl görülen aralık zirvesinin genliği, satışların genel düzeyi yükseldikçe orantılı olarak büyüyor. Bu seri için hangi ayrıştırma modeli daha uygundur?', 'Çarpımsal model', ['Toplamsal model', 'Sabit ortalama modeli', 'Rastgele yürüyüş modeli'], 'Mevsimsel dalgalanma düzeyle orantılı büyüyorsa bileşenler çarpılarak birleştirilir (Y = T × S × I); sabit genlikli dalgalanmada toplamsal model kullanılır.'),
  ('Hassas bir soruda katılımcı gizlice zar atıyor: 1 ya da 2 gelirse ne olursa olsun \'Evet\' diyor, 3–6 gelirse dürüst yanıt veriyor. \'Evet\' oranı %40 çıkmıştır. Gerçek \'evet\' oranının tahmini yüzde kaçtır?', '%10', ['%40', '%20', '%6,7'], 'P(Evet) = 1/3 + (2/3)·p = 0,40 olduğundan p = (0,40 − 1/3) · 3/2 = 0,10 bulunur.'),
  ('Basıklık, dördüncü standartlaştırılmış moment E[(X − μ)⁴] / σ⁴ olarak tanımlanırsa normal dağılımın basıklığı kaçtır?', '3', ['1', '2', '4'], 'Normal dağılım için dördüncü standart moment 3\'tür; bu yüzden \'fazla basıklık\' basıklıktan 3 çıkarılarak tanımlanır ve normalde 0 olur.'),
  ('Aşağıdaki dağılımlardan hangisinin fazla basıklığı negatiftir (normalden daha basık ve kısa kuyrukludur)?', 'Sürekli düzgün dağılım', ['Laplace dağılımı', 'Serbestlik derecesi 5 olan t dağılımı', 'Normal dağılım'], 'Sürekli düzgün dağılımın fazla basıklığı −1,2\'dir; Laplace ve t dağılımlarınınki pozitif, normalinki sıfırdır.'),
  ('0, 0 ve 3 değerlerinden oluşan verinin (ortalama 1) moment çarpıklık katsayısı m₃ / m₂^(3/2) yaklaşık kaçtır?', '0,71', ['0', '−0,71', '1,41'], 'Sapmalar −1, −1, 2\'dir; m₂ = 6/3 = 2, m₃ = (−1 − 1 + 8)/3 = 2. Katsayı 2 / 2^1,5 ≈ 0,71 bulunur; veri sağa çarpıktır.'),
  ('Cauchy dağılımından çekilen örneklemlerde örneklem büyüklüğü artırılsa bile örneklem ortalaması kararlı bir değere yaklaşmaz. Bunun nedeni nedir?', 'Beklenen değeri tanımlı değildir', ['Dağılım yalnız tam sayı değerleri alır', 'Dağılımın varyansı sıfırdır', 'Dağılım simetrik değildir'], 'Cauchy dağılımının kuyrukları o kadar kalındır ki ortalaması (ve varyansı) yoktur; büyük sayılar yasası ve merkezî limit teoremi bu yüzden uygulanamaz.'),
  ('Yetişkinlikte ölüm riskinin yaşla birlikte yaklaşık üstel biçimde arttığını öne süren ve 1825\'te ortaya konan model kimin adıyla anılır?', 'Benjamin Gompertz', ['Thomas Malthus', 'Edmond Halley', 'John Graunt'], 'Gompertz yasasına göre yetişkin ölüm hızı yaklaşık sabit bir oranla, çoğu toplumda kabaca 8 yılda bir iki katına çıkar.'),
  ('Bir hava tahmincisi iki gün için yağış olasılığını 0,8 ve 0,3 vermiş; ilk gün yağmur yağmış (1), ikinci gün yağmamıştır (0). Tahminlerin Brier skoru (olasılık ile sonuç farkının karelerinin ortalaması) kaçtır?', '0,065', ['0,25', '0,13', '0,5'], '((0,8 − 1)² + (0,3 − 0)²) / 2 = (0,04 + 0,09) / 2 = 0,065. Brier skoru ne kadar küçükse olasılık tahminleri o kadar iyidir.'),
  ('İki hilesiz zar atılıyor ve üst yüzlerdeki sayılardan büyük olanı (eşitse o sayı) kaydediliyor. Bu değerin beklenen değeri yaklaşık kaçtır?', '4,47', ['3,5', '5', '6'], 'P(büyük ≤ k) = (k/6)² olduğundan P(büyük = k) = (2k − 1)/36\'dır; Σ k(2k − 1)/36 = 161/36 ≈ 4,47.'),
  ('Bir meta-analizde etki büyüklüğü 2 (varyansı 1) ve 5 (varyansı 2) olan iki çalışma, ağırlıkları varyanslarının tersi olacak biçimde birleştiriliyor. Birleşik etki büyüklüğü kaçtır?', '3', ['3,5', '4', '2,5'], 'Ağırlıklar 1/1 = 1 ve 1/2 = 0,5\'tir: (1 · 2 + 0,5 · 5) / 1,5 = 4,5 / 1,5 = 3.'),
  ('Her kumaş topundaki dokuma hatası sayısını izlemek için kullanılan ve Poisson dağılımına dayanan kontrol çizelgesi hangisidir?', 'c çizelgesi', ['p çizelgesi', 'X̄ çizelgesi', 's çizelgesi'], 'c çizelgesi sabit büyüklükteki bir birimdeki kusur sayısını izler; sınırları c̄ ± 3√c̄ biçiminde hesaplanır.'),
  ('Taguchi\'nin kayıp fonksiyonuna göre bir ürün şartname sınırları içinde kalsa bile neden kayba yol açabilir?', 'Kayıp, hedef değerden sapmanın karesiyle artar', ['Kayıp yalnız şartname sınırları aşılınca başlar', 'Kayıp sapmadan bağımsız sabit bir tutardır', 'Kayıp yalnız üretim miktarına bağlıdır'], 'Taguchi kaybı L = k(y − hedef)² ile modeller; tolerans içinde ama hedeften uzak ürünler de müşteri için maliyet doğurur.'),
  ('Bir istatistiğin değişkenliğini, her seferinde bir gözlemi dışarıda bırakıp istatistiği yeniden hesaplayarak tahmin eden yeniden örnekleme yöntemine ne ad verilir?', 'Jackknife', ['Bootstrap', 'Monte Carlo benzetimi', 'Sistematik örnekleme'], 'Jackknife n ayrı \'birini dışarıda bırak\' tahminiyle yanlılık ve standart hata kestirir; bootstrap ise yerine koyarak yeniden örnekleme yapar.'),
  ('Yirmi mektup yirmi zarfa rastgele yerleştiriliyor. Kendi zarfına giden mektup sayısının beklenen değeri kaçtır?', '1', ['0', '10', '1/20'], 'Her mektubun kendi zarfına gitme olasılığı 1/20\'dir; beklenen değerin doğrusallığıyla toplam 20 · (1/20) = 1 bulunur. Sonuç mektup sayısından bağımsızdır.'),
  ('Aynı 100 kişiye bir reklamdan önce ve sonra \'Ürünü satın alır mısınız? (Evet/Hayır)\' diye soruluyor. Yanıt oranındaki değişimi sınamak için uygun test hangisidir?', 'McNemar testi', ['Ki-kare bağımsızlık testi', 'Bağımsız iki örneklem t testi', 'Kruskal-Wallis testi'], 'McNemar testi eşleştirilmiş ikili verilerde yalnız fikir değiştiren (evet→hayır, hayır→evet) kişilere bakarak değişimi sınar.'),
  ('Bağımsız iki örneklem t testinin klasik biçimini uygulamadan önce grupların varyanslarının eşit olup olmadığını sınamak için kullanılan test hangisidir?', 'Levene testi', ['Shapiro-Wilk testi', 'McNemar testi', 'Wilcoxon işaretli sıra testi'], 'Levene testi grupların varyans eşitliğini sınar; varyanslar farklıysa Welch düzeltmeli t testi tercih edilir.'),
  ('İki ayrı örneklemin aynı sürekli dağılımdan gelip gelmediğini, birikimli dağılım fonksiyonları arasındaki en büyük dikey uzaklığa bakarak sınayan test hangisidir?', 'Kolmogorov-Smirnov testi', ['Levene testi', 'Fisher\'in kesin testi', 'Tukey HSD testi'], 'Kolmogorov-Smirnov istatistiği iki ampirik birikimli dağılım arasındaki en büyük farktır; dağılımın yalnız ortalamasını değil biçimini de karşılaştırır.'),
  ('Bir tarım deneyinde tarlanın hem kuzey-güney nemi hem de doğu-batı toprak yapısı değişiyor. Her işlemin her satırda ve her sütunda tam bir kez yer aldığı tasarıma ne ad verilir?', 'Latin kare tasarımı', ['Tam rastgele tasarım', 'Kartopu tasarımı', 'Eşleştirilmiş grup tasarımı'], 'Latin kare tasarımı iki farklı karıştırıcı kaynağı (satır ve sütun) aynı anda bloklar.'),
  ('Klinik bir deneyde her hasta sırayla hem ilacı hem plaseboyu alıyor, sıralama rastgele belirleniyor ve iki dönem arasında bir arınma süresi bırakılıyor. Bu tasarıma ne ad verilir?', 'Çapraz geçişli tasarım', ['Paralel gruplu tasarım', 'Kesitsel tasarım', 'Vaka-kontrol tasarımı'], 'Çapraz geçişli (crossover) tasarımda her kişi kendi kontrolü olur; arınma süresi önceki tedavinin etkisinin taşınmasını önlemek içindir.'),
];
